<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Masa sewa', href: '/owner/tenancies' }, { title: 'Detail masa sewa', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';

    type Tenancy = { id: number; status: string; property: { id: number; name: string }; room: { id: number; code: string }; resident: { id: number; full_name: string; whatsapp_number: string }; planned_start_date: string; planned_end_exclusive: string; actual_start_date: string | null; actual_check_in_at: string | null; actual_checkout_date: string | null; agreed_monthly_rent_rupiah: number; current_monthly_rent_rupiah: number; billing_anchor_day: number | null; payment_terms: string | null; notes: string | null };
    type Invoice = { id: number; invoice_number: string; due_date: string; cycle_start_date: string | null; cycle_end_exclusive: string | null; lines: { kind: string; description: string; amount_rupiah: number }[]; adjustments: { kind: 'credit' | 'debit'; amount_rupiah: number; reason: string }[]; adjusted_total_rupiah: number; adjustment_label: string | null };
    type DepositAccount = { id: number; required_amount_rupiah: number; booking_id: number | null; tenancy_id: number | null } | null;
    type Extension = { id: number; old_planned_end_exclusive: string; new_planned_end_exclusive: string; old_monthly_rent_rupiah: number; new_monthly_rent_rupiah: number; effective_from: string; reason: string | null };
    let { tenancy, invoices, deposit_account, extensions, actions }: { tenancy: Tenancy; invoices: Invoice[]; deposit_account: DepositAccount; extensions: Extension[]; actions: { can_check_in: boolean; can_cancel: boolean; can_extend: boolean; can_check_out: boolean } } = $props();

    const labels: Record<string, string> = { scheduled: 'Terjadwal', active: 'Aktif', completed: 'Selesai', terminated: 'Dihentikan' };
    const rupiah = (amount: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(amount);
    const originalRentSubtotal = (invoice: Invoice) => invoice.lines.filter((line) => line.kind === 'rent').reduce((sum, line) => sum + line.amount_rupiah, 0);
</script>

<AppHead title={`Masa sewa ${tenancy.id}`} />
<main class="mx-auto w-full max-w-5xl space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-start justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">{tenancy.property.name} · Kamar {tenancy.room.code}</p><h1 class="text-3xl font-semibold tracking-tight">Masa sewa #{tenancy.id}</h1><p class="text-sm text-muted-foreground">Status: {labels[tenancy.status] ?? tenancy.status}</p></div><Link href="/owner/tenancies" class="inline-flex items-center rounded-md border px-4 py-2 text-sm">Daftar masa sewa</Link></header>
    <section class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">Penyewa</p><Link href={`/owner/residents/${tenancy.resident.id}`} class="mt-2 inline-block font-medium underline-offset-4 hover:underline">{tenancy.resident.full_name}</Link><p class="mt-1 text-sm text-muted-foreground">{tenancy.resident.whatsapp_number}</p></article><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">Periode rencana</p><p class="mt-2 font-medium">{tenancy.planned_start_date} – {tenancy.planned_end_exclusive}</p><p class="mt-1 text-xs text-muted-foreground">Tanggal akhir adalah batas eksklusif kamar.</p></article><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">Tarif bulanan efektif saat ini</p><p class="mt-2 text-xl font-semibold">{rupiah(tenancy.current_monthly_rent_rupiah)}</p><p class="text-xs text-muted-foreground">Billing anchor: {tenancy.billing_anchor_day ?? 'menunggu check-in'}{tenancy.billing_anchor_day ? ' setiap bulan' : ''}</p></article></section>
    <section class="grid gap-4 sm:grid-cols-2"><article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Check-in / check-out aktual</h2><dl class="mt-3 space-y-2 text-sm"><div class="flex justify-between gap-3"><dt class="text-muted-foreground">Tanggal check-in</dt><dd>{tenancy.actual_start_date ?? 'Belum dicatat'}</dd></div><div class="flex justify-between gap-3"><dt class="text-muted-foreground">Check-out terakhir ditempati</dt><dd>{tenancy.actual_checkout_date ?? 'Belum dicatat'}</dd></div></dl></article><article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Deposit jaminan</h2><p class="mt-2">{deposit_account ? rupiah(deposit_account.required_amount_rupiah) : 'Belum ditetapkan'}</p><p class="mt-1 text-xs text-muted-foreground">Penerimaan, refund, dan settlement dicatat lewat alur keuangan.</p></article></section>
    {#if tenancy.payment_terms || tenancy.notes}<section class="grid gap-4 sm:grid-cols-2">{#if tenancy.payment_terms}<article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Ketentuan pembayaran</h2><p class="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{tenancy.payment_terms}</p></article>{/if}{#if tenancy.notes}<article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Catatan</h2><p class="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{tenancy.notes}</p></article>{/if}</section>{/if}
    <section class="space-y-3 rounded-xl border bg-card p-5 shadow-sm"><div><h2 class="font-semibold">Invoice</h2><p class="text-sm text-muted-foreground">Invoice pertama terbit saat check-in aktual. Saldo pembayaran akan ditampilkan setelah modul keuangan tersedia.</p></div>{#if invoices.length === 0}<p class="rounded-md border border-dashed p-4 text-sm text-muted-foreground">Belum ada invoice. Tenancy terjadwal belum ditagih.</p>{:else}<div class="space-y-3">{#each invoices as invoice (invoice.id)}<article class="rounded-lg border p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="font-medium">{invoice.invoice_number}</h3><p class="text-sm text-muted-foreground">Jatuh tempo {invoice.due_date}{invoice.cycle_start_date && invoice.cycle_end_exclusive ? ` · siklus ${invoice.cycle_start_date} – ${invoice.cycle_end_exclusive}` : ''}</p></div></div><ul class="mt-3 divide-y text-sm">{#each invoice.lines as line, index (index)}<li class="flex justify-between gap-3 py-2"><span>{line.description}</span><span>{rupiah(line.amount_rupiah)}</span></li>{/each}</ul><dl class="mt-3 space-y-2 border-t pt-3 text-sm"><div class="flex justify-between gap-3"><dt class="text-muted-foreground">Subtotal sewa asli</dt><dd class="font-medium">{rupiah(originalRentSubtotal(invoice))}</dd></div>{#if invoice.adjustments.length > 0}<div class="space-y-1 border-t pt-3"><dt class="font-medium">{invoice.adjustment_label || 'Penyesuaian invoice'}</dt>{#each invoice.adjustments as adjustment, index (index)}<div class="flex justify-between gap-3"><dd class="text-muted-foreground">{adjustment.reason || (adjustment.kind === 'credit' ? 'Kredit prorata' : 'Penyesuaian debit')}</dd><dd class="font-medium">{adjustment.kind === 'credit' ? '− ' : '+ '}{rupiah(adjustment.amount_rupiah)}</dd></div>{/each}</div>{/if}<div class="flex justify-between gap-3 border-t pt-3"><dt class="font-semibold">Total setelah penyesuaian</dt><dd class="font-semibold">{rupiah(invoice.adjusted_total_rupiah)}</dd></div></dl></article>{/each}</div>{/if}</section>
    <section class="space-y-3 rounded-xl border bg-card p-5 shadow-sm"><div><h2 class="font-semibold">Riwayat perpanjangan</h2><p class="text-sm text-muted-foreground">Tarif baru berlaku mulai siklus tagihan berikutnya, atau siklus saat ini jika tepat di batas.</p></div>{#if extensions.length === 0}<p class="text-sm text-muted-foreground">Belum ada perpanjangan.</p>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[38rem] text-left text-sm"><thead class="border-b text-muted-foreground"><tr><th class="py-3 pr-3 font-medium">Tanggal akhir baru</th><th class="py-3 pr-3 font-medium">Tarif lama</th><th class="py-3 pr-3 font-medium">Tarif baru</th><th class="py-3 pr-3 font-medium">Efektif mulai</th><th class="py-3 font-medium">Alasan</th></tr></thead><tbody class="divide-y">{#each extensions as extension (extension.id)}<tr><td class="py-3 pr-3">{extension.old_planned_end_exclusive} → {extension.new_planned_end_exclusive}</td><td class="py-3 pr-3">{rupiah(extension.old_monthly_rent_rupiah)}</td><td class="py-3 pr-3">{rupiah(extension.new_monthly_rent_rupiah)}</td><td class="py-3 pr-3">{extension.effective_from}</td><td class="py-3">{extension.reason || '—'}</td></tr>{/each}</tbody></table></div>{/if}</section>
    <section class="space-y-4"><h2 class="text-lg font-semibold">Tindakan masa sewa</h2>
        {#if actions.can_check_in}<Form action={`/owner/tenancies/${tenancy.id}/check-in`} method="post" class="space-y-4 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Catat check-in aktual</h3><p class="text-sm text-muted-foreground">Billing anchor dan invoice pertama dimulai dari tanggal aktual.</p></div><div class="space-y-2"><label for="actual_start_date" class="text-sm font-medium">Tanggal check-in</label><Input id="actual_start_date" name="actual_start_date" type="date" required /><InputError message={errors.actual_start_date} /></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya mencatat penyewa telah check-in.</span></label><InputError message={errors.tenancy} /><div class="flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Mencatat…' : 'Aktifkan tenancy'}</Button></div>{/snippet}</Form>{/if}
        {#if actions.can_extend}<Form action={`/owner/tenancies/${tenancy.id}/extensions`} method="post" class="space-y-4 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Perpanjang masa sewa</h3><p class="text-sm text-muted-foreground">Konflik booking masa depan akan diperiksa. Tarif baru berlaku pada batas siklus tagihan yang sesuai.</p></div><div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for="new_planned_end_exclusive" class="text-sm font-medium">Kamar tersedia kembali mulai</label><Input id="new_planned_end_exclusive" name="new_planned_end_exclusive" type="date" value={tenancy.planned_end_exclusive} required /><InputError message={errors.new_planned_end_exclusive} /></div><div class="space-y-2"><label for="new_monthly_rent_rupiah" class="text-sm font-medium">Tarif bulanan baru (Rp)</label><Input id="new_monthly_rent_rupiah" name="new_monthly_rent_rupiah" type="number" min="1" step="1" value={tenancy.current_monthly_rent_rupiah} required /><InputError message={errors.new_monthly_rent_rupiah} /></div></div><div class="space-y-2"><label for="extension_reason" class="text-sm font-medium">Catatan kesepakatan</label><textarea id="extension_reason" name="reason" rows={2} maxlength={500} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.reason} /></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya menyetujui perubahan masa sewa ini.</span></label><InputError message={errors.tenancy} /><div class="flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Memeriksa…' : 'Simpan perpanjangan'}</Button></div>{/snippet}</Form>{/if}
        {#if actions.can_check_out}<Form action={`/owner/tenancies/${tenancy.id}/check-out`} method="post" class="space-y-4 rounded-xl border border-amber-300/60 bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Catat check-out</h3><p class="text-sm text-muted-foreground">Masukkan hari terakhir penyewa memakai kamar. Prorata dihitung dengan hari kalender; refund tidak dilakukan otomatis.</p></div><div class="space-y-2"><label for="actual_checkout_date" class="text-sm font-medium">Hari terakhir ditempati</label><Input id="actual_checkout_date" name="actual_checkout_date" type="date" required /><InputError message={errors.actual_checkout_date} /></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya telah mencatat check-out aktual.</span></label><InputError message={errors.tenancy} /><div class="flex justify-end"><Button type="submit" variant="outline" disabled={processing}>{processing ? 'Menyimpan…' : 'Catat check-out'}</Button></div>{/snippet}</Form>{/if}
        {#if actions.can_cancel}<Form action={`/owner/tenancies/${tenancy.id}/cancel`} method="post" class="space-y-3 rounded-xl border border-amber-300/60 bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Batalkan tenancy terjadwal</h3><p class="text-sm text-muted-foreground">Histori tetap disimpan; tanggal mulai yang belum terjadi tidak membuat invoice.</p></div><div class="space-y-2"><label for="cancel_reason" class="text-sm font-medium">Alasan</label><textarea id="cancel_reason" name="reason" rows={2} required maxlength={500} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.reason} /></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya memahami tenancy terjadwal akan dihentikan.</span></label><div class="flex justify-end"><Button type="submit" variant="destructive" disabled={processing}>{processing ? 'Menyimpan…' : 'Batalkan tenancy'}</Button></div>{/snippet}</Form>{/if}
        {#if !actions.can_check_in && !actions.can_extend && !actions.can_check_out && !actions.can_cancel}<p class="rounded-xl border border-dashed p-5 text-sm text-muted-foreground">Tenancy ini sudah ditutup. Histori tetap tersedia untuk ditinjau.</p>{/if}
    </section>
</main>
